func TestEnumSpecialistMessageDeliveryMode(t *testing.T) {
	t.Run("NewFromString_steer", func(t *testing.T) {
		t.Parallel()
		val, err := NewSpecialistMessageDeliveryModeFromString("steer")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, SpecialistMessageDeliveryMode("steer"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_queue", func(t *testing.T) {
		t.Parallel()
		val, err := NewSpecialistMessageDeliveryModeFromString("queue")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, SpecialistMessageDeliveryMode("queue"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewSpecialistMessageDeliveryModeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewSpecialistMessageDeliveryModeFromString("steer")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

